#ifndef SEMANTICS_H
#define SEMANTICS_H

#include "ctx.h"  // Ctx

/**
 * @brief Analyses the program in ctx->ast.
 *
 * Phase 0 inserts the member entries into the global scope, phase 1 (function
 * collection) declares every DEF of the PROGRAM as a function symbol in the
 * global scope, then every function body is checked. Scopes are owned by the
 * AST nodes that open them, so after a THROW ctx_free releases everything the
 * pass created. The pass keeps its state on the C stack and allocates nothing
 * of its own.
 *
 * Errors are reported with THROW: E_SEMANTIC_UNDEFINED_ERROR (3, no @main),
 * E_SEMANTIC_REDEFINITION_ERROR (4, duplicate function or a function named like
 * a built-in, more than one @main), E_SEMANTIC_ARGUMENT_ERROR (5, a @main with
 * a parameter).
 *
 * @param[in,out] ctx Non-null pointer to an allocated context (the built-ins
 * are in ctx->global_symtable), ctx->ast must be a parser-produced PROGRAM
 */
void semantics_analyze(Ctx* ctx);

#endif
